query CopilotCheckPullRequest($owner: String!, $name: String!, $number: Int!) {
  viewer { login }
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      state isDraft isCrossRepository headRefOid mergeable changedFiles
      headRepositoryOwner { login }
      author { login }
      autoMergeRequest { enabledAt }
    }
  }
}
